import React, { useRef, useState } from 'react';

function VoiceControl() {
  const mediaRecorderRef = useRef(null);
  const [isRecording, setIsRecording] = useState(false);

  const startRecording = async () => {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

    const mediaRecorder = new MediaRecorder(stream);
    mediaRecorderRef.current = mediaRecorder;
    const audioChunks = [];

    mediaRecorder.ondataavailable = (event) => {
      if (event.data.size > 0) {
        audioChunks.push(event.data);

        // Send chunk to backend for accent conversion
        sendToBackend(event.data);
      }
    };

    mediaRecorder.onstop = () => {
      setIsRecording(false);
    };

    mediaRecorder.start(1000); // Send chunks every 1s
    setIsRecording(true);
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    setIsRecording(false);
  };

  const sendToBackend = async (audioBlob) => {
    const formData = new FormData();
    formData.append('audio', audioBlob, 'input.wav');

    await fetch('http://localhost:5001/api/convert-accent', {
      method: 'POST',
      body: formData,
    })
      .then(res => res.blob())
      .then(blob => {
        const audioURL = URL.createObjectURL(blob);
        const audio = new Audio(audioURL);
        audio.play();
      });
  };

  return (
    <div className="p-4 border mt-4 rounded">
      <h2 className="font-bold mb-2">Voice Modulation</h2>
      <button
        onClick={isRecording ? stopRecording : startRecording}
        className="px-4 py-2 bg-blue-600 text-white rounded"
      >
        {isRecording ? 'Stop Mic' : 'Start Mic'}
      </button>
    </div>
  );
}

export default VoiceControl;
